create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, timezone text not null default 'Australia/Adelaide', calorie_target integer not null default 2500, protein_target integer not null default 185, water_target_l numeric(4,1) not null default 4.0, onboarding_complete boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.daily_checkins (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, checkin_date date not null, weight_kg numeric(5,2), protein_g integer, water_l numeric(4,1), sleep_hours numeric(4,1), mood text, energy integer check (energy between 1 and 10), body_feel text, trained_today boolean not null default false, training_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, checkin_date));
create table if not exists public.nutrition_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, entry_date date not null, meal_type text not null, name text not null, calories integer not null default 0, protein_g integer not null default 0, carbs_g integer not null default 0, fats_g integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cardio_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, session_date date not null, activity_type text not null, distance_km numeric(8,2) not null default 0, duration_min integer not null default 0, steps integer not null default 0, calories integer not null default 0, effort_zone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.workout_templates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, detail text, exercises jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.training_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null default 'My plan', plan_data jsonb not null default '[]'::jsonb, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.workout_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, template_id uuid references public.workout_templates(id) on delete set null, title text not null, started_at timestamptz, completed_at timestamptz, exercises jsonb not null default '[]'::jsonb, total_volume numeric(12,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.daily_checkins enable row level security; alter table public.nutrition_entries enable row level security; alter table public.cardio_sessions enable row level security; alter table public.workout_templates enable row level security; alter table public.training_plans enable row level security; alter table public.workout_sessions enable row level security;
create policy "profiles own rows" on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy "checkins own rows" on public.daily_checkins for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "nutrition own rows" on public.nutrition_entries for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "cardio own rows" on public.cardio_sessions for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "templates own rows" on public.workout_templates for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "plans own rows" on public.training_plans for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "sessions own rows" on public.workout_sessions for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();